  function useAdminAuth(){const[snapshot,setSnapshot]=React.useState(state);React.useEffect(()=>subscribe(setSnapshot),[]);React.useEffect(()=>{bootstrap();},[]);return Object.assign({},snapshot,{retry,has});}
